// UC-41: Parse Gemini Vision response and extract food inventory array
const geminiResponse = $input.first().json;

// Navigate Gemini API response structure
let aiOutputText = '';
try {
  aiOutputText = geminiResponse.candidates[0].content.parts[0].text;
} catch (e) {
  return [{ json: { 
    success: false, 
    p_raw_inventory: [], 
    error: 'Failed to extract text from Gemini response: ' + e.message 
  }}];
}

// Clean AI output: strip markdown code fences and extra whitespace
let foodArray = [];
try {
  const cleanedOutput = aiOutputText
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/g, '')
    .replace(/^\s*\n/, '')
    .trim();
  foodArray = JSON.parse(cleanedOutput);

  // Validate: ensure it's an array of strings
  if (!Array.isArray(foodArray)) {
    foodArray = [String(foodArray)];
  }
  foodArray = foodArray
    .filter(item => typeof item === 'string' && item.trim().length > 0)
    .map(item => item.trim().toLowerCase());

} catch (e) {
  // Fallback: try to extract items with regex if JSON parse fails
  const matches = aiOutputText.match(/["']([^"']+)["']/g);
  if (matches && matches.length > 0) {
    foodArray = matches.map(m => m.replace(/["']/g, '').trim().toLowerCase());
  } else {
    foodArray = ['error_parsing_ai_output'];
  }
}

// Pass along user_id from webhook for MongoDB query
const userId = $('Receive Refrigerator Image').first().json.body.user_id || '';

return [{ 
  json: { 
    success: true,
    user_id: userId,
    p_raw_inventory: foodArray,
    detected_count: foodArray.length,
    detected_at: new Date().toISOString()
  } 
}];
